UPDATE t_client_business_profile
SET classification_case_id=#{caseId}, classification_confirmed_by=NULL, classification_confirmed_time=NULL, update_time=#{now}
WHERE business_profile_id=#{row.businessProfileId}
  AND (classification_case_id IS NULL OR classification_case_id <> #{caseId} OR classification_confirmed_time IS NULL)

UPDATE t_client_business_profile
SET classification_confirmed_by=#{actorId}, classification_confirmed_time=#{now}, update_time=#{now}
WHERE business_profile_id=#{row.businessProfileId} AND classification_case_id=#{row.classificationCaseId}
  AND classification_confirmed_time IS NULL
